## 🟢 Logic (Step by Step)
1. **Case 1: List is empty (`head == NULL`)**  
   → Print *"List is empty"* and return.

2. **Case 2: Only one node (`head->next == NULL`)**  
   → Free that node and make `head = NULL`.

3. **Case 3: More than one node**  
   - Traverse the list until you reach the **second last node** (the one whose `next->next == NULL`).  
   - Free the last node.  
   - Update `second_last->next = NULL`.

---

## 🟢 Code (C program style)
```c
#include <stdio.h>
#include <stdlib.h>

// Node structure
struct Node {
    int data;
    struct Node* next;
};

struct Node* head = NULL; // global head pointer

// Function to delete node at the end
void deleteAtEnd() {
    // Case 1: Empty list
    if (head == NULL) {
        printf("List is empty. Nothing to delete.\n");
        return;
    }

    // Case 2: Only one node
    if (head->next == NULL) {
        printf("Deleting node with data %d\n", head->data);
        free(head);
        head = NULL;
        return;
    }

    // Case 3: More than one node
    struct Node* temp = head;
    // Traverse to the second last node
    while (temp->next->next != NULL) {
        temp = temp->next;
    }

    printf("Deleting node with data %d\n", temp->next->data);
    free(temp->next);   // free the last node
    temp->next = NULL;  // second last node becomes last
}

// Utility function to insert at end (for testing)
void insertAtEnd(int value) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = value;
    newNode->next = NULL;

    if (head == NULL) {
        head = newNode;
        return;
    }

    struct Node* temp = head;
    while (temp->next != NULL) {
        temp = temp->next;
    }
    temp->next = newNode;
}

// Utility function to display list
void display() {
    struct Node* temp = head;
    if (temp == NULL) {
        printf("List is empty.\n");
        return;
    }
    printf("List: ");
    while (temp != NULL) {
        printf("%d -> ", temp->data);
        temp = temp->next;
    }
    printf("NULL\n");
}

// Main function for testing
int main() {
    insertAtEnd(10);
    insertAtEnd(20);
    insertAtEnd(30);
    insertAtEnd(40);

    display();

    deleteAtEnd();
    display();

    deleteAtEnd();
    display();

    deleteAtEnd();
    display();

    deleteAtEnd(); // deletes last node
    display();

    deleteAtEnd(); // tries on empty list
    return 0;
}
```

